.c04-toolbar-list{max-height:45dvh;overflow:auto;overscroll-behavior:contain;display:grid;gap:3px}
.c04-toolbar-row{display:flex;gap:4px;align-items:center;border:1px solid var(--a-border,#ddd);border-radius:7px;padding:4px 5px}
.c04-toolbar-row label{display:flex;align-items:center;flex:1;min-width:0;gap:5px;font-size:11px}
.c04-toolbar-row label span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.c04-toolbar-row input{flex:none;width:18px;height:18px}
.c04-toolbar-row button{min-width:37px;min-height:37px;border:1px solid var(--a-border,#ddd);border-radius:7px;background:transparent;color:inherit}
.c04-toolbar-settings>button{min-height:38px;border:1px solid var(--a-border,#ddd);border-radius:7px;background:var(--a-accent-soft,#fff6d7);color:inherit;margin-top:8px}
.c04-toolbar-settings output{display:block;min-height:18px;font-size:11px;color:var(--a-subtle,#667)}

.c04-simple-macros{padding:8px 2px;margin:10px 8px;border-top:1px solid var(--a-border,#ddd);font-size:12px}
.c04-simple-macros summary{min-height:38px;font-weight:600;padding:8px 0;cursor:pointer}
.c04-simple-macros p{font-size:11px;line-height:1.5;color:var(--a-subtle,#667)}
.c04-simple-macros>input,.c04-simple-macros>select{display:block;width:100%;min-height:38px;margin:5px 0;padding:6px;border:1px solid var(--a-border,#ddd);border-radius:7px;color:inherit;background:var(--a-surface,#fff)}
.c04-macro-steps{max-height:32dvh;overflow:auto;display:flex;flex-direction:column;gap:5px;margin:8px 0}
.c04-macro-step{display:flex;align-items:center;gap:4px;border:1px solid var(--a-border,#ddd);border-radius:7px;padding:5px}
.c04-macro-step span{flex:1;min-width:0;font-size:11px;overflow:hidden;text-overflow:ellipsis}
.c04-macro-step button{min-width:35px;min-height:36px;border:1px solid var(--a-border,#ddd);border-radius:7px;background:transparent;color:inherit}
.c04-simple-macros .c04-workspace-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px}
.c04-simple-macros .c04-workspace-actions button{min-height:40px;border:1px solid var(--a-border,#ddd);background:var(--a-accent-soft,#fff2d7);border-radius:8px;font-size:11px;color:inherit}
.c04-simple-macros output{display:block;min-height:20px;margin:6px 0;font-size:11px;color:var(--a-subtle,#667)}

color/harmony.css:
.c04-color-harmony{padding:9px 5px;border-top:1px solid var(--a-border,#ddd);font-size:11px}
.c04-color-harmony summary{cursor:pointer;font-weight:650;min-height:34px}
.c04-color-harmony>section{display:flex;flex-direction:column;gap:8px}
.c04-color-harmony select{width:100%;min-height:36px;padding:5px;border:1px solid var(--a-border,#ddd);border-radius:8px}
.c04-harmony-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px}
.c04-harmony-swatch{min-width:0;display:flex;flex-direction:column;align-items:stretch;gap:3px;background:transparent;border:1px solid var(--a-border,#ddd);border-radius:8px;padding:6px;color:inherit}
.c04-harmony-swatch i{display:block;height:26px;border-radius:6px;border:1px solid #0002}
.c04-harmony-swatch span{font-size:11px;font-weight:600}
.c04-harmony-swatch small{font-size:10px;color:var(--a-subtle,#667)}
.c04-color-harmony output{font-size:11px;color:var(--a-text,#333)}
.c04-color-harmony label{display:flex;align-items:center;min-height:32px;gap:5px}
.c04-color-harmony label input{flex:none}
.c04-color-harmony p{margin:2px 0;color:var(--a-subtle,#667);line-height:1.4}
/* Proof only the painted image. Pixel coordinates, crop handles and brush cursor stay legible. */
body.c04-gray-proof .surface > #canvas,
body.c04-gray-proof .surface > .illustro-document-presentation,
body.c04-gray-proof .surface > .illustro-stroke-overlay{filter:grayscale(1)}

.c04-secondary-color{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:5px 8px;border-bottom:1px solid var(--a-border,#ddd);font-size:11px}
.c04-secondary-color label{display:flex;align-items:center;gap:7px}
.c04-secondary-color input[type=color]{width:39px;height:35px;border:1px solid var(--a-border,#ddd);border-radius:7px;background:transparent;cursor:pointer}
.c04-secondary-color button{border:1px solid var(--a-border,#ddd);border-radius:7px;background:transparent;min-height:37px;padding:5px 8px;color:inherit;font-size:11px}

.c04-palette-folder-label{display:flex;flex-direction:column;gap:5px;font-size:11px;margin:8px 0}
.c04-palette-folder-label input,.c04-color-tags{min-height:34px;width:100%;font-size:11px;padding:6px;border:1px solid var(--a-border,#ddd);border-radius:7px;background:var(--a-surface,#fff);color:inherit}
.color-swatch-cell:has(.c04-color-tags){display:flex;flex-wrap:wrap;align-items:center;gap:3px}
.color-swatch-cell .c04-color-tags{flex:1 1 100%;min-width:110px}

.c04-color-harmony label:has(select){display:flex;flex-direction:column;align-items:stretch;gap:4px}
.c04-color-harmony label select{min-width:0;width:100%}
.c04-color-harmony small{font-size:10px;line-height:1.45;color:var(--a-subtle,#667)}
body[data-c04-vision="protan"] .surface > #canvas,
body[data-c04-vision="protan"] .surface > .illustro-document-presentation,
body[data-c04-vision="protan"] .surface > .illustro-stroke-overlay{filter:url("#c04-vision-protan")}
body[data-c04-vision="deutan"] .surface > #canvas,
body[data-c04-vision="deutan"] .surface > .illustro-document-presentation,
body[data-c04-vision="deutan"] .surface > .illustro-stroke-overlay{filter:url("#c04-vision-deutan")}
body[data-c04-vision="tritan"] .surface > #canvas,
body[data-c04-vision="tritan"] .surface > .illustro-document-presentation,
body[data-c04-vision="tritan"] .surface > .illustro-stroke-overlay{filter:url("#c04-vision-tritan")}

.c04-color-opacity{padding:7px 9px;font-size:11px}
#c04ColorOpacityStatus{display:block;font-size:10px;color:var(--a-subtle,#667);padding:0 9px}

/* Reference sampling is an isolated temporary view, not an artwork layer. */
.color-sample-options .color-detail-inner{display:flex;flex-direction:column;gap:7px}
.color-sample-options label{display:flex;flex-direction:column;align-items:stretch;gap:4px;font-size:11px}
.color-sample-options select{width:100%;min-height:38px;border:1px solid var(--a-border,#ddd);border-radius:7px;padding:6px;background:var(--a-surface,#fff);color:inherit}
.color-sample-options #colorSampleLayerLabel[hidden]{display:none!important}
#referenceSampleOpen{padding:8px;min-height:40px;border-radius:8px;border:1px solid var(--a-border,#ddd);background:var(--a-accent-soft,#fff3d9);color:inherit}
.c04-reference-sample-dialog{position:fixed;top:7dvh;left:50%;transform:translateX(-50%);margin:0;padding:15px;width:min(620px,calc(100vw - 22px));max-height:86dvh;overflow:auto;z-index:32;border:1px solid var(--a-border-strong,#ccc);border-radius:14px;background:var(--a-surface,#fff);color:inherit;box-shadow:0 20px 55px #171b2848}
.c04-reference-sample-dialog::backdrop{background:#111a3155}
.c04-reference-sample-dialog h2{margin:0 0 8px;font-size:17px}
.c04-reference-sample-dialog p{font-size:11px;line-height:1.45;margin:4px 0 10px;color:var(--a-subtle,#667)}
.c04-reference-sample-canvas{display:block;max-width:100%;max-height:57dvh;margin:0 auto;border:1px solid var(--a-border,#ddd);border-radius:7px;cursor:crosshair;object-fit:contain;image-rendering:auto}
.c04-reference-sample-pair{display:flex;align-items:center;gap:10px;margin:9px 0;flex-wrap:wrap}
.c04-reference-sample-pair span{display:flex;align-items:center;gap:6px;font-size:11px}
.c04-reference-sample-pair i{display:inline-block;width:27px;height:27px;border:1px solid var(--a-border,#ddd);border-radius:6px}
.c04-reference-sample-dialog output{display:block;font-size:11px;min-height:18px}
.c04-reference-sample-dialog small{display:block;font-size:10px;line-height:1.4;color:var(--a-subtle,#667);margin:7px 0}
.c04-reference-sample-dialog .c04-workspace-actions{display:flex;flex-wrap:wrap;gap:7px}
.c04-reference-sample-dialog button{min-height:40px;border:1px solid var(--a-border,#ddd);padding:7px 10px;border-radius:8px;background:var(--a-accent-soft,#fff3d9);color:inherit}

.color-sample-current{display:block;margin:3px 0 5px;padding:6px 8px;border-radius:7px;background:var(--a-surface-soft,#fff);color:var(--a-text,#333);font-size:11px;line-height:1.5}

ui/floatingPanels.css:
/* C04 detachable panels live in document.body, outside the scrolling dock. */
.c04-panel-placeholder{min-height:43px;margin-bottom:8px;padding:5px 8px;display:flex;align-items:center;justify-content:space-between;gap:8px;border:1px dashed var(--a-border-strong,#c8c7c0);border-radius:8px;color:var(--a-subtle,#63676b);font-size:11px}
.c04-panel-placeholder button{min-height:32px;border:1px solid var(--a-border,#ddd);border-radius:7px;padding:5px 8px;background:var(--a-surface,#fff);color:inherit}
.workspace-box.c04-panel-float{position:fixed!important;margin:0!important;z-index:23!important;max-width:calc(100vw - 16px);max-height:calc(100dvh - 16px);min-height:170px;min-width:240px;box-shadow:0 13px 46px #10182855;display:flex;flex-direction:column;overflow:hidden;border:1px solid var(--a-border-strong,#c6c4be);border-radius:12px}
.c04-panel-float .box-heading{flex:none;min-width:0;background:var(--a-surface-soft,#fbfbfa);border-bottom:1px solid var(--a-border,#ddd)}
.c04-panel-float .box-body{min-height:0;flex:1;overflow-y:auto;overscroll-behavior:contain;padding-bottom:28px}
.c04-panel-float .box-more-menu{z-index:25;position:absolute}
.c04-float-handle{flex:none;min-width:39px;min-height:34px;touch-action:none;cursor:grab;border:1px solid var(--a-border,#ddd);border-radius:6px;background:var(--a-accent-soft,#ffeebe);font-size:10px;color:inherit}
.c04-float-handle:active{cursor:grabbing}
.c04-float-resize{position:absolute;right:1px;bottom:1px;z-index:9;touch-action:none;cursor:nwse-resize;min-width:39px;min-height:39px;border:1px solid var(--a-border-strong,#ccc);border-radius:8px 0 8px 0;background:var(--a-accent-soft,#ffeebe);color:inherit;font-size:21px}
.c04-float-menu{width:100%;min-height:36px;text-align:left}
body.illustro-focus-mode>.c04-panel-float{display:none!important}
@media(max-width:760px){.workspace-box.c04-panel-float{min-width:240px}.c04-float-handle{min-width:44px;min-height:40px}}

effects/rasterPanel.css:
.raster-effect-recipe { list-style:none; display:grid; gap:4px; padding:0; }
.raster-effect-recipe li { display:flex; flex-wrap:wrap; align-items:center; gap:4px; }
.raster-effect-recipe [aria-pressed="true"] { font-weight:700; }
.raster-effect-comparison:not([hidden]) { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:8px; }
.raster-effect-comparison figure { margin:0; }
.raster-effect-comparison canvas { max-width:100%; height:auto; background:repeating-conic-gradient(#ddd 0% 25%,#fff 0% 50%) 0 0/12px 12px; }
